#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0 OR ISC OR MIT-0
# Rewrites skills/results/upstream.txt from rind-results' main. A diff means the skill may be stale.
set -euo pipefail
repo=steelhead99x/rind-results
out=skills/results/upstream.txt
files=(AGENTS.md CONTRIBUTING.md results/README.md quests/README.md)
sha=$(gh api "repos/$repo/commits/main" --jq .sha)
{
  echo "# rind-results files skills/results/SKILL.md was checked against."
  echo "# path sha256 (or absent). Regenerated by .github/scripts/results-drift.sh."
  for f in "${files[@]}"; do
    if body=$(gh api -H 'Accept: application/vnd.github.raw' "repos/$repo/contents/$f?ref=$sha" 2>/dev/null); then
      printf '%s %s\n' "$f" "$(printf '%s' "$body" | sha256sum | cut -d' ' -f1)"
    else
      printf '%s absent\n' "$f"
    fi
  done
} > "$out"
echo "$sha" > "$out.commit"
